package pe.nexo.store.order.dto;import pe.nexo.store.order.CustomerOrder;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;public record OrderResponse(Long id,String orderNumber,String status,BigDecimal total,LocalDateTime createdAt,List<OrderLineResponse>items){public static OrderResponse from(CustomerOrder order){return new OrderResponse(order.getId(),order.getOrderNumber(),order.getStatus().name(),order.getTotal(),order.getCreatedAt(),order.getItems().stream().map(i->new OrderLineResponse(i.getProductId(),i.getProductName(),i.getQuantity(),i.getLineTotal())).toList());}public record OrderLineResponse(Long productId,String productName,Integer quantity,BigDecimal lineTotal){}}
